// Détecte un pic anormal de volume de tickets (vs période précédente).
const data = $input.first().json || {};
const current = data.current || {};
const previous = data.previous || {};
const delta = data.deltaTickets != null ? Number(data.deltaTickets) : 0;

const SEUIL_PCT = 50;   // alerte si +50% de volume
const MIN_TICKETS = 10; // évite le bruit sur de faibles volumes

const curTotal = current.totalTickets || 0;
const prevTotal = previous.totalTickets || 0;

// Pas de pic → on arrête (aucun email)
if (!(delta >= SEUIL_PCT && curTotal >= MIN_TICKETS)) {
  return [];
}

const now = new Date().toLocaleString('fr-FR');
const html = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:600px;margin:0 auto;">
  <div style="background:linear-gradient(135deg,#B71C1C,#E53935);color:white;padding:25px;border-radius:12px 12px 0 0;text-align:center;">
    <h1 style="margin:0;">🚨 Pic d'activité détecté</h1>
    <p style="margin:6px 0 0;opacity:0.9;">Volume en hausse de <strong>+${delta.toFixed(0)}%</strong> — ${now}</p>
  </div>
  <div style="background:white;padding:25px;border:1px solid #e0e0e0;">
    <p>Le volume de réclamations dépasse le seuil d'alerte (+${SEUIL_PCT}%). Une montée en charge ou un incident est possible.</p>
    <table style="width:100%;border-collapse:collapse;">
      <tr style="background:#FFEBEE;"><td style="padding:10px;"><strong>Période actuelle</strong></td><td style="padding:10px;text-align:right;font-weight:700;color:#C62828;">${curTotal} tickets</td></tr>
      <tr><td style="padding:10px;"><strong>Période précédente</strong></td><td style="padding:10px;text-align:right;font-weight:700;">${prevTotal} tickets</td></tr>
      <tr style="background:#FFEBEE;"><td style="padding:10px;"><strong>Variation</strong></td><td style="padding:10px;text-align:right;font-weight:700;color:#C62828;">+${delta.toFixed(0)}%</td></tr>
      <tr><td style="padding:10px;">☎️ Appels / ✉️ Emails / 🌐 Web</td><td style="padding:10px;text-align:right;">${current.ticketsCall||0} / ${current.ticketsEmail||0} / ${current.ticketsWeb||0}</td></tr>
    </table>
    <p style="margin-top:15px;"><a href="http://localhost:3000/dashboard" style="color:#C62828;font-weight:700;">→ Vérifier le tableau de bord</a></p>
  </div>
  <div style="background:#f8f9fa;padding:15px;border-radius:0 0 12px 12px;text-align:center;color:#888;font-size:12px;">
    <p>© 2026 AutoAssist — Supervision proactive n8n</p>
  </div>
</div>`;

return [{ json: { html, subject: '🚨 Pic d\'activité AutoAssist — +' + delta.toFixed(0) + '%' } }];
